def accepted_encoding_outputs(port):
    result = {}
    for item in CHECKS:
        for mode in ('positive', 'reject'):
            claim = item['positive' if mode == 'positive' else 'negative']
            binder = ' ' if item['parameters'] else ' : '
            text = item['imports']+'\nlemma checked'+binder+claim+'.\nproof.\n  '+item['proof']+'\nqed.\n'
            stem = 'accepted_encoding_'+item['name'].replace('-', '_')+'_'+mode
            result[port/'scratch'/(stem+'.ec')] = text
    return result

def accepted_encoding_rows():
    rows = []
    for item in CHECKS:
        stem = 'scratch/accepted_encoding_'+item['name'].replace('-', '_')
        # The closed empty-list proposition simplifies to false before the
        # exact tactic reports its failure; the other mutations retain terms.
        diagnostic = '[by]: cannot close goals' if item['name'] == 'empty-pool' else 'the given proof-term proves:'
        rows += [stem+'_positive.ec\tMUST-PASS\t-', stem+'_reject.ec\tMUST-FAIL\t'+diagnostic]
    return rows
